functions.hash_fnv1a:
static const uint64_t hash_fnv1a(const char *key, const size_t klen)
{
    static const uint64_t fnv_prime = 1099511628211ULL;
    static const uint64_t fnv_offset_bias = 14695981039346656037ULL;
    const int iterations = klen;
    uint8_t i;
    uint64_t hash = fnv_offset_bias;
    for (i = 0; i < iterations; i++)
    {
        hash = hash ^ key[i];
        hash = hash * fnv_prime;
    }
    return hash;
}

functions.charbit:
static const uint32_t charbit(const uint32_t position)
{
    return position >> 5;
}

functions.modbit:
static const uint32_t modbit(const uint32_t position)
{
    return 1 << (position & 31);
}

functions.popcount_32:
static inline uint32_t popcount_32(uint32_t x)
{
    const uint32_t m1 = 0x55555555;
    const uint32_t m2 = 0x33333333;
    const uint32_t m4 = 0x0f0f0f0f;
    x -= (x >> 1) & m1;
    x = (x & m2) + ((x >> 2) & m2);
    x = (x + (x >> 4)) & m4;
    x += x >> 8;
    return (x + (x >> 16)) & 0x3f;
}

functions.position_to_offset:
static const uint32_t position_to_offset(const uint32_t *bitmap, const uint32_t position)
{
    uint32_t retval = 0;
    uint32_t pos = position;
    uint32_t bitmap_iter = 0;
    for (; pos >= (sizeof(uint32_t) * 8); pos -= (sizeof(uint32_t) * 8))
        retval += popcount_32(bitmap[bitmap_iter++]);
    return retval + popcount_32(bitmap[bitmap_iter] & (((uint32_t)1 << pos) - 1u));
}

functions.is_position_occupied:
static const int is_position_occupied(const uint32_t *bitmap, const uint32_t position)
{
    return bitmap[charbit(position)] & modbit(position);
}

functions.set_position:
static void set_position(uint32_t *bitmap, const uint32_t position)
{
    bitmap[charbit(position)] |= modbit(position);
}

functions._sparse_array_group_set:
static const int _sparse_array_group_set(struct sparse_array_group *arr, const uint32_t i, const void *val,
                                         const size_t vlen)
{
    uint32_t offset = 0;
    void *destination = ((void *)0);
    if (vlen > arr->elem_size)
        return 0;
    offset = position_to_offset(arr->bitmap, i);
    if (!is_position_occupied(arr->bitmap, i))
    {
        const size_t to_move_siz = (arr->count - offset) * (arr->elem_size + sizeof(size_t));
        void *new_group = realloc(arr->group, (arr->count + 1) * (arr->elem_size + sizeof(size_t)));
        if (new_group == ((void *)0))
            return 0;
        if (to_move_siz > 0)
        {
            memmove((unsigned char *)(new_group) + ((offset + 1) * (arr->elem_size + sizeof(size_t))),
                    (unsigned char *)(new_group) + (offset * (arr->elem_size + sizeof(size_t))), to_move_siz);
        }
        arr->count++;
        arr->group = new_group;
        set_position(arr->bitmap, i);
    }
    destination = (unsigned char *)(arr->group) + (offset * (arr->elem_size + sizeof(size_t)));
    memcpy(destination, &vlen, sizeof(vlen));
    destination = (unsigned char *)destination + sizeof(vlen);
    memcpy(destination, val, vlen);
    return 1;
}

functions._sparse_array_group_get:
static const void *_sparse_array_group_get(struct sparse_array_group *arr, const uint32_t i, size_t *outsize)
{
    const uint32_t offset = position_to_offset(arr->bitmap, i);
    const unsigned char *item_siz = (unsigned char *)(arr->group) + (offset * (arr->elem_size + sizeof(size_t)));
    const void *item = item_siz + sizeof(size_t);
    if (!is_position_occupied(arr->bitmap, i))
        return ((void *)0);
    if (*(size_t *)item_siz == 0)
        return ((void *)0);
    if (outsize)
        memcpy(outsize, item_siz, sizeof(size_t));
    return item;
}

functions._sparse_array_group_free:
static const int _sparse_array_group_free(struct sparse_array_group *arr)
{
    free(arr->group);
    return 1;
}

functions.sparse_array_init:
struct sparse_array *sparse_array_init(const size_t element_size, const uint32_t maximum)
{
    unsigned int i = 0;
    struct sparse_array *arr = ((void *)0);
    arr = calloc(1, sizeof(struct sparse_array));
    if (arr == ((void *)0))
        return ((void *)0);
    struct sparse_array stack_array = {
        .maximum = maximum,
    };
    memcpy(arr, &stack_array, sizeof(struct sparse_array));
    arr->groups = calloc(((arr->maximum - 1) / 48 + 1), sizeof(struct sparse_array_group));
    if (arr->groups == ((void *)0))
    {
        free(arr);
        return ((void *)0);
    }
    for (i = 0; i < ((arr->maximum - 1) / 48 + 1); i++)
    {
        struct sparse_array_group *sag = &arr->groups[i];
        sag->elem_size = element_size;
    }
    return arr;
}

functions.sparse_array_set:
const int sparse_array_set(struct sparse_array *arr, const uint32_t i, const void *val, const size_t vlen)
{
    if (i > arr->maximum)
        return 0;
    struct sparse_array_group *operating_group = &arr->groups[i / 48];
    const int position = i % 48;
    return _sparse_array_group_set(operating_group, position, val, vlen);
}

functions.sparse_array_get:
const void *sparse_array_get(struct sparse_array *arr, const uint32_t i, size_t *outsize)
{
    if (i > arr->maximum)
        return ((void *)0);
    struct sparse_array_group *operating_group = &arr->groups[i / 48];
    const int position = i % 48;
    return _sparse_array_group_get(operating_group, position, outsize);
}

functions.sparse_array_free:
const int sparse_array_free(struct sparse_array *arr)
{
    unsigned int i = 0;
    for (; i < ((arr->maximum - 1) / 48 + 1); i++)
    {
        struct sparse_array_group *sag = &arr->groups[i];
        _sparse_array_group_free(sag);
    }
    free(arr->groups);
    free(arr);
    return 1;
}

