functions._create_and_insert_new_bucket:
static const int _create_and_insert_new_bucket(struct sparse_array *array, const unsigned int i, const char *key,
                                               const size_t klen, const void *value, const size_t vlen,
                                               const uint64_t key_hash)
{
    void *copied_value = ((void *)0);
    char *copied_key = ((void *)0);
    copied_value = malloc(vlen + klen);
    if (copied_value == ((void *)0))
        goto error;
    memcpy(copied_value, value, vlen);
    copied_key = copied_value + vlen;
    strncpy(copied_key, key, klen);
    struct sparse_bucket bct = {.key = copied_key, .klen = klen, .val = copied_value, .vlen = vlen, .hash = key_hash};
    if (!sparse_array_set(array, i, &bct, sizeof(bct)))
        goto error;
    return 1;
error:
    free(copied_value);
    return 0;
}

functions._rehash_and_grow_table:
static const int _rehash_and_grow_table(struct sparse_dict *dict)
{
    unsigned int i = 0, buckets_rehashed = 0;
    const size_t new_bucket_max = dict->bucket_max * 2;
    struct sparse_array *new_buckets = ((void *)0);
    new_buckets = sparse_array_init(sizeof(struct sparse_bucket), new_bucket_max);
    if (new_buckets == ((void *)0))
        goto error;
    for (i = 0; i < dict->bucket_max; i++)
    {
        size_t bucket_siz = 0;
        const struct sparse_bucket *bucket = sparse_array_get(dict->buckets, i, &bucket_siz);
        if (bucket_siz != 0 && bucket != ((void *)0))
        {
            unsigned int probed_val = 0, num_probes = 0;
            uint64_t key_hash = bucket->hash;
            while (1)
            {
                probed_val = (key_hash + num_probes * num_probes) & (new_bucket_max - 1);
                size_t current_value_siz = 0;
                const void *current_value = sparse_array_get(new_buckets, probed_val, &current_value_siz);
                if (current_value_siz == 0 && current_value == ((void *)0))
                    break;
                if (num_probes > dict->bucket_count)
                    goto error;
                num_probes++;
            }
            if (!sparse_array_set(new_buckets, probed_val, bucket, sizeof(struct sparse_bucket)))
                goto error;
            buckets_rehashed++;
        }
        if (buckets_rehashed == dict->bucket_count)
            break;
    }
    sparse_array_free(dict->buckets);
    dict->buckets = new_buckets;
    dict->bucket_max = new_bucket_max;
    return 1;
error:
    if (new_buckets)
        sparse_array_free(new_buckets);
    return 0;
}

functions.sparse_dict_set:
const int sparse_dict_set(struct sparse_dict *dict, const char *key, const size_t klen, const void *value,
                          const size_t vlen)
{
    const uint64_t key_hash = hash_fnv1a(key, klen);
    unsigned int num_probes = 0;
    while (1)
    {
        size_t current_value_siz = 0;
        const unsigned int probed_val = (key_hash + num_probes * num_probes) & (dict->bucket_max - 1);
        const void *current_value = sparse_array_get(dict->buckets, probed_val, &current_value_siz);
        if (current_value_siz == 0 && current_value == ((void *)0))
        {
            if (_create_and_insert_new_bucket(dict->buckets, probed_val, key, klen, value, vlen, key_hash))
                break;
            else
                goto error;
        }
        else
        {
            struct sparse_bucket *existing_bucket = (struct sparse_bucket *)current_value;
            if (existing_bucket->hash == key_hash && existing_bucket->klen == klen &&
                strncmp(existing_bucket->key, key, klen) == 0)
            {
                char *existing_key = existing_bucket->key;
                void *existing_val = existing_bucket->val;
                if (_create_and_insert_new_bucket(dict->buckets, probed_val, key, klen, value, vlen, key_hash))
                {
                    free(existing_key);
                    free(existing_val);
                    return 1;
                }
                else
                {
                    goto error;
                }
            }
        }
        num_probes++;
        if (num_probes > dict->bucket_count)
        {
            printf("Could not find an open slot in the table.\n");
            goto error;
        }
    }
    dict->bucket_count++;
    if (dict->bucket_count / (float)dict->bucket_max >= 80 / 100.0f)
        return _rehash_and_grow_table(dict);
    return 1;
error:
    return 0;
}

functions.sparse_dict_get:
const void *sparse_dict_get(struct sparse_dict *dict, const char *key, const size_t klen, size_t *outsize)
{
    const uint64_t key_hash = hash_fnv1a(key, klen);
    unsigned int num_probes = 0;
    while (1)
    {
        size_t current_value_siz = 0;
        const unsigned int probed_val = (key_hash + num_probes * num_probes) & (dict->bucket_max - 1);
        const void *current_value = sparse_array_get(dict->buckets, probed_val, &current_value_siz);
        if (current_value_siz != 0 && current_value != ((void *)0))
        {
            struct sparse_bucket *existing_bucket = (struct sparse_bucket *)current_value;
            if (existing_bucket->hash == key_hash && existing_bucket->klen == klen &&
                strncmp(existing_bucket->key, key, klen) == 0)
            {
                if (outsize)
                    memcpy(outsize, &existing_bucket->vlen, sizeof(existing_bucket->vlen));
                return existing_bucket->val;
            }
        }
        else
        {
            return ((void *)0);
        }
        num_probes++;
        if (num_probes > dict->bucket_count)
            return ((void *)0);
    }
    return ((void *)0);
}

functions.sparse_dict_free:
const int sparse_dict_free(struct sparse_dict *dict)
{
    unsigned int i = 0;
    for (i = 0; i < dict->bucket_max; i++)
    {
        size_t current_value_siz = 0;
        const void *current_value = sparse_array_get(dict->buckets, i, &current_value_siz);
        if (current_value_siz != 0 && current_value != ((void *)0))
        {
            struct sparse_bucket *existing_bucket = (struct sparse_bucket *)current_value;
            free(existing_bucket->val);
        }
    }
    sparse_array_free(dict->buckets);
    free(dict);
    return 1;
}
